import http from 'node:http';
import crypto from 'node:crypto';
import fs from 'node:fs';
import { db } from './db.js';

const PORT = process.env.PORT || 3000;
const yen = n => '¥' + Number(n).toLocaleString('ja-JP');
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const q = (sql, ...a) => db.prepare(sql).all(...a);
const q1 = (sql, ...a) => db.prepare(sql).get(...a);
const run = (sql, ...a) => db.prepare(sql).run(...a);

// ---------- auth helpers ----------
const hash = (pw, salt) => crypto.scryptSync(pw, salt, 64).toString('hex');
function getSession(req, res) {
  const m = /sid=([a-f0-9]{32})/.exec(req.headers.cookie || '');
  let s = m && q1('SELECT * FROM sessions WHERE id=?', m[1]);
  if (!s) {
    const id = crypto.randomBytes(16).toString('hex');
    run('INSERT INTO sessions(id,created) VALUES(?,?)', id, Date.now());
    res.setHeader('Set-Cookie', `sid=${id}; HttpOnly; SameSite=Lax; Path=/; Max-Age=2592000`);
    s = { id, user_id: null };
  }
  return s;
}

// ---------- layout ----------
function layout(ctx, title, body) {
  const { user, cartCount, flash } = ctx;
  return `<!doctype html><html lang="ja"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} | ミニショップ</title>
<link rel="stylesheet" href="/style.css"></head><body>
<header><a class="logo" href="/">🛍️ ミニショップ</a>
<form action="/" method="get"><input name="q" placeholder="商品を検索" value="${esc(ctx.query?.get('q') || '')}"><button>検索</button></form>
${user ? `<a href="/orders">注文履歴</a><span>${esc(user.name)}さん</span>
<form action="/logout" method="post" style="flex:0"><button class="sub">ログアウト</button></form>`
      : `<a href="/login">ログイン</a><a href="/register">新規登録</a>`}
<a href="/cart">🛒 カート(${cartCount})</a></header>
<main>${flash ? `<div class="flash ${flash.err ? 'err' : ''}">${esc(flash.msg)}</div>` : ''}${body}</main>
<footer>© ミニショップ(デモサイト・実際の決済は行われません)</footer></body></html>`;
}

// ---------- cart ----------
const cartRows = sid => q(`SELECT p.*, c.qty FROM cart_items c JOIN products p ON p.id=c.product_id WHERE c.session_id=? ORDER BY p.id`, sid);
const cartTotal = rows => rows.reduce((s, r) => s + r.price * r.qty, 0);

// ---------- pages ----------
const pages = {
  home(ctx) {
    const cat = ctx.query.get('category'), term = ctx.query.get('q');
    let sql = 'SELECT * FROM products WHERE 1=1'; const args = [];
    if (cat) { sql += ' AND category=?'; args.push(cat); }
    if (term) { sql += ' AND (name LIKE ? OR description LIKE ?)'; args.push(`%${term}%`, `%${term}%`); }
    const items = q(sql + ' ORDER BY id', ...args);
    const cats = q('SELECT DISTINCT category FROM products ORDER BY category').map(r => r.category);
    return layout(ctx, '商品一覧', `
<div class="cats"><a href="/" class="${!cat ? 'on' : ''}">すべて</a>
${cats.map(c => `<a class="${c === cat ? 'on' : ''}" href="/?category=${encodeURIComponent(c)}">${esc(c)}</a>`).join('')}</div>
${items.length ? `<div class="grid">${items.map(p => `
<div class="card"><a href="/product/${p.id}" class="emoji">${p.emoji}</a>
<a href="/product/${p.id}">${esc(p.name)}</a><span class="muted">${esc(p.category)}</span>
<span class="price">${yen(p.price)}</span>
${p.stock > 0 ? `<form method="post" action="/cart/add"><input type="hidden" name="id" value="${p.id}"><button>カートに入れる</button></form>` : '<span class="muted">在庫切れ</span>'}
</div>`).join('')}</div>` : '<p>該当する商品がありません。</p>'}`);
  },
  product(ctx, id) {
    const p = q1('SELECT * FROM products WHERE id=?', id);
    if (!p) return null;
    return layout(ctx, p.name, `<div class="box detail"><div class="emoji">${p.emoji}</div><div>
<h1>${esc(p.name)}</h1><p class="muted">${esc(p.category)}</p><p>${esc(p.description)}</p>
<p class="price">${yen(p.price)}</p>
<p class="muted">${p.stock > 0 ? `在庫: ${p.stock}点` : '在庫切れ'}</p>
${p.stock > 0 ? `<form method="post" action="/cart/add"><input type="hidden" name="id" value="${p.id}">
数量 <input type="number" name="qty" value="1" min="1" max="${p.stock}"> <button>カートに入れる</button></form>` : ''}
</div></div><a href="/">← 商品一覧へ</a>`);
  },
  cart(ctx) {
    const rows = cartRows(ctx.session.id);
    if (!rows.length) return layout(ctx, 'カート', '<div class="box">カートは空です。<a href="/">買い物を続ける</a></div>');
    return layout(ctx, 'カート', `<div class="box"><h1>カート</h1><table>
<tr><th>商品</th><th>単価</th><th>数量</th><th class="right">小計</th><th></th></tr>
${rows.map(r => `<tr><td>${r.emoji} <a href="/product/${r.id}">${esc(r.name)}</a></td><td>${yen(r.price)}</td>
<td><form method="post" action="/cart/update" style="display:flex;gap:6px"><input type="hidden" name="id" value="${r.id}">
<input type="number" name="qty" value="${r.qty}" min="0" max="${r.stock}"><button class="sub">更新</button></form></td>
<td class="right">${yen(r.price * r.qty)}</td>
<td><form method="post" action="/cart/update"><input type="hidden" name="id" value="${r.id}"><input type="hidden" name="qty" value="0"><button class="danger">削除</button></form></td></tr>`).join('')}
</table><p class="right price">合計: ${yen(cartTotal(rows))}</p>
<p class="right"><a class="btn" href="/checkout">レジに進む</a></p></div>`);
  },
  checkout(ctx) {
    if (!ctx.user) return 'redirect:/login?next=/checkout';
    const rows = cartRows(ctx.session.id);
    if (!rows.length) return 'redirect:/cart';
    return layout(ctx, 'ご注文手続き', `<div class="box"><h1>ご注文手続き</h1>
<table>${rows.map(r => `<tr><td>${esc(r.name)} × ${r.qty}</td><td class="right">${yen(r.price * r.qty)}</td></tr>`).join('')}
<tr><th>合計</th><th class="right">${yen(cartTotal(rows))}</th></tr></table>
<form method="post" action="/checkout"><label>お名前</label><input name="name" required value="${esc(ctx.user.name)}">
<label>配送先住所</label><textarea name="address" rows="3" required></textarea>
<p class="muted">お支払い: 代金引換(デモのため実際の決済はありません)</p>
<button>注文を確定する</button></form></div>`);
  },
  orders(ctx) {
    if (!ctx.user) return 'redirect:/login?next=/orders';
    const os = q('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC', ctx.user.id);
    return layout(ctx, '注文履歴', `<h1>注文履歴</h1>${os.length ? os.map(o => `<div class="box">
<b>注文番号 #${o.id}</b> <span class="muted">${esc(o.created)}</span><br>
<span class="muted">お届け先: ${esc(o.address)}</span>
<table>${q('SELECT * FROM order_items WHERE order_id=?', o.id).map(i => `<tr><td>${esc(i.name)} × ${i.qty}</td><td class="right">${yen(i.price * i.qty)}</td></tr>`).join('')}
<tr><th>合計</th><th class="right">${yen(o.total)}</th></tr></table></div>`).join('') : '<div class="box">注文履歴はありません。</div>'}`);
  },
  login(ctx) {
    return layout(ctx, 'ログイン', `<div class="box" style="max-width:420px"><h1>ログイン</h1>
<form method="post" action="/login"><input type="hidden" name="next" value="${esc(ctx.query.get('next') || '/')}">
<label>メールアドレス</label><input type="email" name="email" required>
<label>パスワード</label><input type="password" name="password" required><br><br>
<button>ログイン</button> <a href="/register">新規登録</a></form></div>`);
  },
  register(ctx) {
    return layout(ctx, '新規登録', `<div class="box" style="max-width:420px"><h1>新規登録</h1>
<form method="post" action="/register"><label>お名前</label><input name="name" required>
<label>メールアドレス</label><input type="email" name="email" required>
<label>パスワード(8文字以上)</label><input type="password" name="password" minlength="8" required><br><br>
<button>登録する</button></form></div>`);
  },
};

// ---------- POST handlers ----------
const posts = {
  '/cart/add'(ctx, f) {
    const id = +f.get('id'), qty = Math.max(1, +f.get('qty') || 1);
    const p = q1('SELECT * FROM products WHERE id=?', id);
    if (!p) return ['/', '商品が見つかりません', true];
    const cur = q1('SELECT qty FROM cart_items WHERE session_id=? AND product_id=?', ctx.session.id, id)?.qty || 0;
    const n = Math.min(p.stock, cur + qty);
    run('INSERT INTO cart_items VALUES(?,?,?) ON CONFLICT(session_id,product_id) DO UPDATE SET qty=excluded.qty', ctx.session.id, id, n);
    return ['/cart', `「${p.name}」をカートに追加しました`];
  },
  '/cart/update'(ctx, f) {
    const id = +f.get('id'), qty = Math.floor(+f.get('qty'));
    const p = q1('SELECT stock FROM products WHERE id=?', id);
    if (!p || !(qty >= 0)) return ['/cart', '不正な数量です', true];
    if (qty === 0) run('DELETE FROM cart_items WHERE session_id=? AND product_id=?', ctx.session.id, id);
    else run('UPDATE cart_items SET qty=? WHERE session_id=? AND product_id=?', Math.min(qty, p.stock), ctx.session.id, id);
    return ['/cart', 'カートを更新しました'];
  },
  '/register'(ctx, f) {
    const email = f.get('email').trim().toLowerCase(), name = f.get('name').trim(), pw = f.get('password');
    if (!name || !email || pw.length < 8) return ['/register', '入力内容を確認してください(パスワードは8文字以上)', true];
    if (q1('SELECT 1 FROM users WHERE email=?', email)) return ['/register', 'このメールアドレスは既に登録されています', true];
    const salt = crypto.randomBytes(16).toString('hex');
    const r = run('INSERT INTO users(email,name,pass_hash,salt) VALUES(?,?,?,?)', email, name, hash(pw, salt), salt);
    run('UPDATE sessions SET user_id=? WHERE id=?', r.lastInsertRowid, ctx.session.id);
    return ['/', '登録が完了しました'];
  },
  '/login'(ctx, f) {
    const u = q1('SELECT * FROM users WHERE email=?', f.get('email').trim().toLowerCase());
    const ok = u && crypto.timingSafeEqual(Buffer.from(hash(f.get('password'), u.salt), 'hex'), Buffer.from(u.pass_hash, 'hex'));
    if (!ok) return ['/login', 'メールアドレスまたはパスワードが違います', true];
    run('UPDATE sessions SET user_id=? WHERE id=?', u.id, ctx.session.id);
    const next = f.get('next') || '/';
    return [/^\/(?!\/)/.test(next) ? next : '/', 'ログインしました'];
  },
  '/logout'(ctx) {
    run('DELETE FROM cart_items WHERE session_id=?', ctx.session.id);
    run('DELETE FROM sessions WHERE id=?', ctx.session.id);
    return ['/', 'ログアウトしました', false, true];
  },
  '/checkout'(ctx, f) {
    if (!ctx.user) return ['/login', 'ログインが必要です', true];
    const rows = cartRows(ctx.session.id);
    if (!rows.length) return ['/cart', 'カートは空です', true];
    db.exec('BEGIN IMMEDIATE');
    try {
      for (const r of rows) {
        const res = run('UPDATE products SET stock=stock-? WHERE id=? AND stock>=?', r.qty, r.id, r.qty);
        if (res.changes === 0) throw new Error(`「${r.name}」の在庫が不足しています`);
      }
      const o = run('INSERT INTO orders(user_id,name,address,total) VALUES(?,?,?,?)', ctx.user.id, f.get('name'), f.get('address'), cartTotal(rows));
      for (const r of rows) run('INSERT INTO order_items VALUES(?,?,?,?,?)', o.lastInsertRowid, r.id, r.name, r.price, r.qty);
      run('DELETE FROM cart_items WHERE session_id=?', ctx.session.id);
      db.exec('COMMIT');
      return ['/orders', `ご注文ありがとうございます(注文番号 #${o.lastInsertRowid})`];
    } catch (e) {
      db.exec('ROLLBACK');
      return ['/cart', e.message, true];
    }
  },
};

// ---------- server ----------
const flashes = new Map(); // sid -> {msg, err}
const readBody = req => new Promise((ok, ng) => {
  let b = ''; req.on('data', c => { b += c; if (b.length > 1e5) { req.destroy(); ng(new Error('too large')); } });
  req.on('end', () => ok(new URLSearchParams(b)));
});

http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://x');
    if (req.method === 'GET' && url.pathname === '/style.css') {
      res.writeHead(200, { 'Content-Type': 'text/css' });
      return res.end(fs.readFileSync(new URL('./public/style.css', import.meta.url)));
    }
    const session = getSession(req, res);
    const user = session.user_id ? q1('SELECT id,name,email FROM users WHERE id=?', session.user_id) : null;
    const ctx = { session, user, query: url.searchParams,
      cartCount: q1('SELECT COALESCE(SUM(qty),0) n FROM cart_items WHERE session_id=?', session.id).n,
      flash: flashes.get(session.id) };
    flashes.delete(session.id);
    const send = (code, body, h = {}) => { res.writeHead(code, { 'Content-Type': 'text/html; charset=utf-8', ...h }); res.end(body); };

    if (req.method === 'POST') {
      const h = posts[url.pathname];
      if (!h) return send(404, 'Not Found');
      const origin = req.headers.origin;
      if (origin && new URL(origin).host !== req.headers.host) return send(403, 'Forbidden');
      const [to, msg, err, fresh] = h(ctx, await readBody(req));
      if (msg && !fresh) flashes.set(session.id, { msg, err });
      res.writeHead(303, { Location: to }); return res.end();
    }
    let out = null;
    const p = url.pathname;
    if (p === '/') out = pages.home(ctx);
    else if (/^\/product\/\d+$/.test(p)) out = pages.product(ctx, +p.split('/')[2]);
    else if (pages[p.slice(1)] && p !== '/home' && p !== '/product') out = pages[p.slice(1)](ctx);
    if (out === null) return send(404, layout(ctx, '404', '<div class="box">ページが見つかりません。</div>'));
    if (out.startsWith('redirect:')) { res.writeHead(302, { Location: out.slice(9) }); return res.end(); }
    send(200, out);
  } catch (e) {
    console.error(e); res.writeHead(500); res.end('Internal Server Error');
  }
}).listen(PORT, () => console.log(`http://localhost:${PORT}`));
